#!/usr/bin/env bash
# Builds everything a release publishes, from a tag:
#
#   bash .github/ci/release_prep.sh vX.Y.Z [OUT_DIR]      # OUT_DIR defaults to ./dist
#
#   gavel-lint-<os>_<arch>      prebuilt helper binaries (see lint/toolchain/)
#   gavel-tools-vX.Y.Z.tar.gz   the BCR source archive, with the release stamp applied
#
# The stamp exists only in the archive, never in git: it flips IS_RELEASE in
# MODULE.bazel and writes lint/toolchain/integrity.bzl (version + sha256 of each
# binary). Development builds gavel-lint from source; the stamped archive
# downloads these binaries instead, so consumers never compile Go for gavel.
#
# The one archive holds every module (the root gavel_tools and modules/<lang>,
# each published to the BCR from its own root, see .bcr/config.yml). They are
# released from one tag, so each MODULE.bazel must be at the tag's version and
# pin its gavel_tools* bazel_deps to it; the stamp checks that for all of them.
#
# GAVEL_RELEASE_TREEISH   what to archive instead of the tag (default: the tag);
#                         for rehearsing on an uncommitted tree.
# GAVEL_RELEASE_STAMP_VERSION=1  stamp the tag's version into every MODULE.bazel instead of
#                         requiring it to match (local rehearsals only).

set -euo pipefail

die() {
  echo "release_prep: $*" >&2
  exit 1
}

TAG="${1:-}"
OUT_DIR="${2:-dist}"
[[ "${TAG}" =~ ^v[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?$ ]] ||
  die "usage: release_prep.sh vX.Y.Z [OUT_DIR] (got '${TAG}')"
VERSION="${TAG#v}"
TREEISH="${GAVEL_RELEASE_TREEISH:-${TAG}}"

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "${ROOT}"
mkdir -p "${OUT_DIR}"
OUT_DIR="$(cd "${OUT_DIR}" && pwd)"

# The platforms must match GAVEL_LINT_PLATFORMS in lint/toolchain/repositories.bzl;
# the archive check below fails the release if one is missing from the stamp.
PLATFORMS=(darwin_amd64 darwin_arm64 linux_amd64 linux_arm64)

sha256_of() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | cut -d' ' -f1
  else
    shasum -a 256 "$1" | cut -d' ' -f1
  fi
}

# --- Binaries ---------------------------------------------------------------
# Static, stripped, path-independent builds so the same source gives the same
# bytes on any runner. gavel-lint is pure Go (no cgo).
for platform in "${PLATFORMS[@]}"; do
  CGO_ENABLED=0 GOOS="${platform%_*}" GOARCH="${platform#*_}" \
    go build -trimpath -buildvcs=false -ldflags="-s -w" \
    -o "${OUT_DIR}/gavel-lint-${platform}" ./lint/cmd/gavel-lint
done

# A binary that cannot even print its usage must not ship.
host="$(go env GOOS)_$(go env GOARCH)"
if [ -x "${OUT_DIR}/gavel-lint-${host}" ]; then
  usage="$("${OUT_DIR}/gavel-lint-${host}" 2>&1 || true)"
  [[ "${usage}" == *"usage: gavel-lint <tool>"* ]] ||
    die "smoke test failed for gavel-lint-${host}: ${usage}"
fi

# --- Source archive with the release stamp ---------------------------------
ARCHIVE="${OUT_DIR}/gavel-tools-${TAG}.tar.gz"
PREFIX="gavel-tools-${VERSION}"
STAMP_VERSION="${GAVEL_RELEASE_STAMP_VERSION:-0}"

integrity_entries=""
for platform in "${PLATFORMS[@]}"; do
  integrity_entries+="    \"${platform}\": \"$(sha256_of "${OUT_DIR}/gavel-lint-${platform}")\",
"
done

RAW_TAR="$(mktemp)"
trap 'rm -f "${RAW_TAR}"' EXIT
git archive --format=tar --prefix="${PREFIX}/" "${TREEISH}" >"${RAW_TAR}"

# Rewrite the two stamped members and leave every other byte of the git archive
# alone; no timestamps are added, so the same inputs give the same checksum.
INTEGRITY_ENTRIES="${integrity_entries}" VERSION="${VERSION}" PREFIX="${PREFIX}" \
  STAMP_VERSION="${STAMP_VERSION}" RAW_TAR="${RAW_TAR}" ARCHIVE="${ARCHIVE}" \
  python3 -I - <<'PY'
import gzip, io, os, re, sys, tarfile

version = os.environ["VERSION"]
prefix = os.environ["PREFIX"]
module_path = f"{prefix}/MODULE.bazel"
integrity_path = f"{prefix}/lint/toolchain/integrity.bzl"

integrity = f'''"""Release stamp for the prebuilt gavel-lint binaries.

Generated by .github/ci/release_prep.sh for this release; the committed
placeholder (version 0.0.0, no entries) means "build from source".
"""

GAVEL_LINT_VERSION = "{version}"

# platform ("<os>_<arch>") -> sha256 hex of its gavel-lint binary.
GAVEL_LINT_INTEGRITY = {{
{os.environ["INTEGRITY_ENTRIES"]}}}
'''

def patch_module(text, path):
    """Checks (or, in a rehearsal, stamps) the version of a module and of its
    gavel_tools* bazel_deps; only the root module also flips IS_RELEASE."""
    if path == module_path:
        text, flips = re.subn(r"(?m)^IS_RELEASE = False$", "IS_RELEASE = True", text)
        if flips != 1:
            sys.exit("release_prep: expected exactly one `IS_RELEASE = False` in MODULE.bazel")
    declared = re.search(r'(?m)^    version = "([^"]+)",$', text)
    if not declared:
        sys.exit(f"release_prep: no module version found in {path}")
    dep = re.compile(r'(?m)^(bazel_dep\(name = "gavel_tools[a-z_]*", version = ")([^"]+)(")')
    stale = [declared.group(1)] if declared.group(1) != version else []
    stale += [m.group(2) for m in dep.finditer(text) if m.group(2) != version]
    if stale:
        if os.environ["STAMP_VERSION"] != "1":
            sys.exit(f"release_prep: {path} carries version(s) {sorted(set(stale))} != tag version {version}")
        text = text.replace(declared.group(0), f'    version = "{version}",', 1)
        text = dep.sub(lambda m: m.group(1) + version + m.group(3), text)
    return text

def is_module_file(name):
    return name == module_path or re.fullmatch(re.escape(prefix) + r"/modules/[^/]+/MODULE\.bazel", name)

seen = set()
out = io.BytesIO()
with tarfile.open(os.environ["RAW_TAR"]) as src, tarfile.open(fileobj=out, mode="w", format=tarfile.PAX_FORMAT) as dst:
    for member in src:
        data = src.extractfile(member).read() if member.isfile() else None
        if is_module_file(member.name):
            data = patch_module(data.decode(), member.name).encode()
        elif member.name == integrity_path:
            data = integrity.encode()
        if is_module_file(member.name) or member.name == integrity_path:
            seen.add(member.name)
            member.size = len(data)
        dst.addfile(member, io.BytesIO(data) if data is not None else None)
missing = {module_path, integrity_path} - seen
if missing or len(seen) < 3:
    sys.exit(f"release_prep: archive lacks {sorted(missing)} or the modules/<lang> module files (saw {sorted(seen)})")

with open(os.environ["ARCHIVE"], "wb") as raw:
    # mtime=0 keeps the gzip header free of the build time.
    with gzip.GzipFile(filename="", mode="wb", fileobj=raw, mtime=0) as gz:
        gz.write(out.getvalue())
PY

# Every platform must be stamped, or that platform's consumers cannot build.
stamp="$(tar -xzOf "${ARCHIVE}" "${PREFIX}/lint/toolchain/integrity.bzl")"
for platform in "${PLATFORMS[@]}"; do
  grep -q "\"${platform}\": \"[0-9a-f]\{64\}\"" <<<"${stamp}" ||
    die "integrity stamp is missing ${platform}"
done

echo "release_prep: wrote ${ARCHIVE} and gavel-lint-{${PLATFORMS[*]}} in ${OUT_DIR}"
